insert into public.past_presidents (id, created_at, created_by, updated_at, updated_by, name_en, name_bn, term_start, term_end, organization_en, organization_bn, photo, bio_en, bio_bn, email, show_contact, sort_order, is_published)
values
  ('10157124-808b-4737-8cec-f8cacc18fb3d', '2026-10-01T09:00:00.000Z', null, '2026-10-01T09:00:00.000Z', null, 'Mohammed Zahirul Islam (Rinku)', 'মোহাম্মদ জহিরুল ইসলাম (রিংকু)', 2025, 2026, 'Managing Director, PHP Ship Breaking and Recycling Industries Ltd', 'ব্যবস্থাপনা পরিচালক, পিএইচপি শিপ ব্রেকিং অ্যান্ড রিসাইক্লিং ইন্ডাস্ট্রিজ লিমিটেড', '/photos/mohammed-zahirul-islam.jpg', 'Served as Acting President and long-standing Vice President of BSBRA. Spearheaded Bangladesh''s green recycling revolution, achieving the nation''s first HKC Statement of Compliance in 2017.', 'বিএসবিআরএ-এর ভারপ্রাপ্ত সভাপতি ও দীর্ঘকালীন সহ-সভাপতি হিসেবে দায়িত্ব পালন করেন। ২০১৭ সালে দেশের প্রথম এইচকেসি স্টেটমেন্ট অব কমপ্লায়েন্স অর্জনকারী গ্রিন ইয়ার্ড প্রতিষ্ঠা করেন।', 'zahir@phpfamily.com', false, 1, true),
  ('5aef6b33-ef8f-4aa4-bf9d-1aad9f20193e', '2026-10-01T09:00:00.000Z', null, '2026-10-01T09:00:00.000Z', null, 'Alhaj Mohammad Abu Taher', 'আলহাজ্ব মোহাম্মদ আবু তাহের', 2014, 2024, 'Chairman, Taher Group / Taher & Company Ltd', 'চেয়ারম্যান, তাহের গ্রুপ / তাহের অ্যান্ড কোম্পানি লিমিটেড', '/photos/alhaj-mohammad-abu-taher.jpg', 'Long-standing President of BSBRA across consecutive terms. Represented the domestic ship recycling industry before the Ministry of Industries, IMO, and international maritime delegations.', 'বিএসবিআরএ-এর দীর্ঘকালীন সভাপতি যিনি টানা একাধিক মেয়াদে দায়িত্ব পালন করেন। শিল্প মন্ত্রণালয়, আইএমও ও আন্তর্জাতিক প্রতিনিধিদের সামনে দেশীয় শিল্পের স্বার্থ তুলে ধরেন।', null, false, 2, true),
  ('542f4c7e-4fb8-4c8b-952a-c2f00005a235', '2026-10-01T09:00:00.000Z', null, '2026-10-01T09:00:00.000Z', null, 'Hefazatur Rahman', 'হেফাজতুর রহমান', 2011, 2014, 'Chairman, Mostafa Hakim Group / HM Shipping Lines Ltd', 'চেয়ারম্যান, মোস্তফা হাকিম গ্রুপ / এইচএম শিপিং লাইনস লিমিটেড', null, 'Elected President of the association from 2011 to 2014, leading institutional engagement for occupational health, environmental clearance frameworks, and worker welfare.', '২০১১ থেকে ২০১৪ মেয়াদের নির্বাচিত সভাপতি, যিনি শ্রমিকের পেশাগত স্বাস্থ্য ও পরিবেশগত ছাড়পত্র কাঠামো তৈরিতে বলিষ্ঠ ভূমিকা পালন করেন।', null, false, 3, true),
  ('d7b954e3-91a2-4cd4-8b58-6f79e66f275a', '2026-10-01T09:00:00.000Z', null, '2026-10-01T09:00:00.000Z', null, 'Amzad Hossain Chowdhury', 'আমজাদ হোসেন চৌধুরী', 2008, 2011, 'Former President, Bangladesh Ship Breakers Association', 'সাবেক সভাপতি, বাংলাদেশ শিপ ব্রেকার্স অ্যাসোসিয়েশন', null, 'Veteran industrialist and former President of the association during the formative transition toward regulated coastal ship dismantling.', 'প্রবীণ শিল্পপতি এবং উপকূলীয় নিয়মতান্ত্রিক জাহাজভাঙা কার্যক্রমের সূচনালগ্নে সংগঠনের সভাপতি।', null, false, 4, true),
  ('41f649fc-9494-4353-89c5-8e22a4e8edc1', '2026-10-01T09:00:00.000Z', null, '2026-10-01T09:00:00.000Z', null, 'Alhaj Md. Shahjahan', 'আলহাজ্ব মো. শাহজাহান', 2004, 2008, 'Chairman & Managing Director, Kabir Steel Ltd (KSRM)', 'চেয়ারম্যান ও ব্যবস্থাপনা পরিচালক, কবির স্টিল লিমিটেড (কেএসআরএম)', '/photos/alhaj-md-shahjahan.jpg', 'Eminent maritime industrialist and pioneer of modern steel re-rolling and compliant ship recycling facilities in Chattogram.', 'বিশিষ্ট শিল্পপতি এবং চট্টগ্রামে আধুনিক রি-রোলিং মিলস ও আধুনিক জাহাজ পুনর্ব্যবহার স্থাপনার পথপ্রদর্শক।', 'karim@ksrm.com.bd', false, 5, true)
insert into public.meeting_minutes (id, created_at, created_by, updated_at, updated_by, meeting_no, venue, summary_en, summary_bn, file_path, file_name, file_size, mime_type, status, approved_at, access_level, title_en, title_bn, meeting_type, meeting_date)
