  ('e4248d85-2b4f-4966-8dc1-f97bc0b651d4', '2026-10-01T09:00:00.000Z', null, '2026-10-01T09:00:00.000Z', null, 'EC/2026/03', 'BSBRA Secretariat, Chattogram', 'Review of HKC certification progress, Yard Safety Week planning and the digital platform launch.', 'এইচকেসি সনদ অগ্রগতি পর্যালোচনা, ইয়ার্ড সেফটি উইক পরিকল্পনা ও ডিজিটাল প্ল্যাটফর্ম চালু।', null, null, null, null, 'approved', '2026-10-01T09:00:00.000Z', 'members', 'Executive Committee meeting — September 2026', 'কার্যনির্বাহী কমিটির সভা — সেপ্টেম্বর ২০২৬', 'executive_committee', '2026-09-08'),
  ('e3248bf2-2c4f-4af9-8cc1-f7e8c1b65367', '2026-10-01T09:00:00.000Z', null, '2026-10-01T09:00:00.000Z', null, 'EC/2026/02', 'BSBRA Secretariat, Chattogram', 'Budget for 2026–27, sub-committee formation and engagement with the BSRB.', '২০২৬–২৭ বাজেট, উপ-কমিটি গঠন ও বিএসআরবির সঙ্গে সম্পৃক্ততা।', null, null, null, null, 'approved', '2026-10-01T09:00:00.000Z', 'internal', 'Executive Committee meeting — August 2026', 'কার্যনির্বাহী কমিটির সভা — আগস্ট ২০২৬', 'executive_committee', '2026-08-11'),
  ('e62490ab-354f-4924-8bc1-f655b6b64216', '2026-10-01T09:00:00.000Z', null, '2026-10-01T09:00:00.000Z', null, 'EC/2026/01', 'BSBRA Secretariat, Chattogram', 'Handover, portfolio allocation and priorities for the term.', 'দায়িত্ব হস্তান্তর, দায়িত্ব বণ্টন ও মেয়াদের অগ্রাধিকার।', null, null, null, null, 'approved', '2026-10-01T09:00:00.000Z', 'members', 'First meeting of the 2026–2028 Executive Committee', '২০২৬–২০২৮ কার্যনির্বাহী কমিটির প্রথম সভা', 'executive_committee', '2026-07-12'),
  ('20b5df19-d649-4450-9450-a523f4e7180a', '2026-10-01T09:00:00.000Z', null, '2026-10-01T09:00:00.000Z', null, null, 'BSBRA Secretariat, Chattogram', null, null, null, null, null, null, 'draft', null, 'internal', 'Board meeting — October 2026 (draft)', 'বোর্ড সভা — অক্টোবর ২০২৬ (খসড়া)', 'board', '2026-10-06')
